namespace FOC.Tests
{
    public sealed class ArmyRecruitmentLogisticsTests
    {
        [Test]public void ArmyIdentity_IsTypedDuplicateSafeAndDeterministicallyOrdered(){var r=new ArmyRegistry();r.Add(BareArmy("z"));r.Add(BareArmy("a"));Assert.That(r.OrderedArmies.Select(x=>x.Id.Value),Is.EqualTo(new[]{"a","z"}));Assert.Throws<InvalidOperationException>(()=>r.Add(BareArmy("a")));Assert.That(typeof(ArmyState).IsAssignableFrom(typeof(OrganizationState)),Is.False);}
        [Test]public void UnitGroupIdentity_RejectsNegativeAndConflictingArmyMembership(){Assert.Throws<ArgumentOutOfRangeException>(()=>new UnitGroupState(UnitGroupId.Create("bad"),ArmyId.Create("a"),RecruitmentSourceId.Create("source"),"troop",-1));var registry=new ArmyRegistry();var state=new CampaignMilitaryState(registry);var a=BareArmy("a");var b=BareArmy("b");registry.Add(a);registry.Add(b);state.RestoreUnit(Unit("unit",a.Id));Assert.Throws<InvalidOperationException>(()=>state.RestoreUnit(Unit("unit",b.Id)));}
        [Test]public void RecruitmentTypes_AreSourceKindsNotTroopDefinitions(){Assert.That(Enum.GetValues(typeof(RecruitmentType)).Cast<RecruitmentType>(),Is.EquivalentTo(new[]{RecruitmentType.Retinue,RecruitmentType.TimarService,RecruitmentType.CentralSalaried,RecruitmentType.Garrison,RecruitmentType.LocalLevy,RecruitmentType.Mercenary,RecruitmentType.Irregular}));Assert.That(typeof(RecruitmentSourceState).GetProperty("Type")!.PropertyType,Is.EqualTo(typeof(RecruitmentType)));Assert.That(typeof(UnitGroupState).GetProperty("TroopDefinitionId")!.PropertyType,Is.EqualTo(typeof(string)));}
        [Test]public void Recruitment_ConsumesFiniteSourceAndCreatesRealUnitAndRecord(){var c=Context();c.Commands.Recruit(RecruitmentRecordId.Create("record"),c.Source.Id,c.Army.Id,UnitGroupId.Create("unit"),"azap",30,T(0));Assert.That(c.Source.AvailableHeadcount,Is.EqualTo(20));Assert.That(c.Army.Headcount,Is.EqualTo(30));Assert.That(c.Runtime.Military.RecruitmentRecords.OrderedRecords.Single().Headcount,Is.EqualTo(30));Assert.Throws<InvalidOperationException>(()=>c.Commands.Recruit(RecruitmentRecordId.Create("record-2"),c.Source.Id,c.Army.Id,UnitGroupId.Create("unit-2"),"azap",21,T(0)));Assert.That(c.Source.AvailableHeadcount,Is.EqualTo(20));}
        [Test]public void Recruitment_RejectsWrongWorldTimeAndDuplicateRecordWithoutMutation(){var c=Context();Assert.Throws<InvalidOperationException>(()=>c.Commands.Recruit(RecruitmentRecordId.Create("record"),c.Source.Id,c.Army.Id,UnitGroupId.Create("unit"),"azap",10,T(1)));Assert.That(c.Source.AvailableHeadcount,Is.EqualTo(50));c.Commands.Recruit(RecruitmentRecordId.Create("record"),c.Source.Id,c.Army.Id,UnitGroupId.Create("unit"),"azap",10,T(0));Assert.Throws<InvalidOperationException>(()=>c.Commands.Recruit(RecruitmentRecordId.Create("record"),c.Source.Id,c.Army.Id,UnitGroupId.Create("other"),"azap",10,T(0)));Assert.That(c.Source.AvailableHeadcount,Is.EqualTo(40));}
        [Test]public void Recruitment_RequiresRealActiveMilitaryInstitution(){var c=Context(registerSource:false);var missing=new RecruitmentSourceState(RecruitmentSourceId.Create("bad"),RecruitmentType.Garrison,10,c.Authority,c.City.Id,CityBuildingId.Create("missing"));Assert.Throws<InvalidOperationException>(()=>c.Commands.RegisterRecruitmentSource(missing));Assert.That(c.Runtime.Military.RecruitmentSources.Count,Is.Zero);}
        [Test]public void TimarAndMercenary_RequireExplicitServiceOrContractReference(){var authority=Authority();Assert.Throws<ArgumentException>(()=>new RecruitmentSourceState(RecruitmentSourceId.Create("timar"),RecruitmentType.TimarService,10,authority));Assert.Throws<ArgumentException>(()=>new RecruitmentSourceState(RecruitmentSourceId.Create("merc"),RecruitmentType.Mercenary,10,authority));Assert.That(new RecruitmentSourceState(RecruitmentSourceId.Create("timar"),RecruitmentType.TimarService,10,authority,obligationOrContractId:"service-grant").Type,Is.EqualTo(RecruitmentType.TimarService));}
        [Test]public void Commander_IsRealCharacterWithArmyAssignmentAndPhysicalPresence(){var c=Context();Assert.That(c.Army.Commander!.CharacterId,Is.EqualTo(c.Commander.Id));Assert.That(c.Runtime.Characters.GetRequired(c.Army.Commander.CharacterId),Is.TypeOf<CharacterState>());Assert.That(c.Army.Owner.Id,Is.Not.EqualTo(c.Army.Commander.CharacterId.Value));}
        [Test]public void CaptiveOrFakeCharacter_CannotCommand(){var c=Context(createArmy:false);c.Commander.Capture(new CaptivityState(c.Manager.Id,CaptivitySite.InCity(c.City.Id)),T(0));Assert.Throws<InvalidOperationException>(()=>c.Commands.CreateArmy(Army(c)));var fake=new ArmyState(c.ArmyId,"Fake",ArmyOwnerRef.Organization(c.Organization.Id),ArmyOwnerRef.Organization(c.Organization.Id),ArmyLocation.InCity(c.City.Id),new ArmyCommanderReference(CharacterId.Create("missing"),c.Organization.Id,c.Assignment.Id));Assert.Throws<System.Collections.Generic.KeyNotFoundException>(()=>c.Commands.CreateArmy(fake));}
        [Test]public void MilitaryClique_CannotOwnArmyOrCreateTroopsOrCombatBonus(){Assert.That(Enum.GetNames(typeof(ArmyOwnerKind)),Does.Not.Contain("Clique"));Assert.That(typeof(ArmyOwnerRef).GetMethods().Select(x=>x.Name),Does.Not.Contain("Clique"));Assert.That(typeof(CampaignMilitaryState).GetProperties().Any(x=>x.Name.Contains("Clique")||x.Name.Contains("CombatBonus")),Is.False);}
        [Test]public void CommandHierarchy_RejectsCyclesTwoParentsAndArmyAsChild(){var army=ArmyId.Create("army");var h=new CommandHierarchy(army);var a=CommandNodeRef.Unit(UnitGroupId.Create("a"));var b=CommandNodeRef.Unit(UnitGroupId.Create("b"));h.Add(new CommandRelationship(CommandNodeRef.Army(army),a));Assert.Throws<InvalidOperationException>(()=>h.Add(new CommandRelationship(b,a)));Assert.Throws<InvalidOperationException>(()=>h.Add(new CommandRelationship(a,CommandNodeRef.Army(army))));var cycle=new CommandHierarchy(army);cycle.Add(new CommandRelationship(a,b));Assert.Throws<InvalidOperationException>(()=>cycle.Add(new CommandRelationship(b,a)));}
        [Test]public void CitySupplyTransfer_IsRealConservativeAndAtomic(){var c=Context();var before=c.Market.Stock.QuantityOf(c.Food.Id);c.Supply.TransferFromCity(c.City.Id,c.Army.Id,c.Food.Id,25);Assert.That(c.Market.Stock.QuantityOf(c.Food.Id),Is.EqualTo(before-25));Assert.That(c.Army.Supply.QuantityOf(c.Food.Id),Is.EqualTo(25));Assert.Throws<InvalidOperationException>(()=>c.Supply.TransferFromCity(c.City.Id,c.Army.Id,c.Food.Id,1000));Assert.That(c.Market.Stock.QuantityOf(c.Food.Id)+c.Army.Supply.QuantityOf(c.Food.Id),Is.EqualTo(before));}
        [Test]public void CaravanSupplyTransfer_DecreasesCargoAndDoesNotDuplicateGoods(){var c=Context();var before=c.Caravan.Cargo.QuantityOf(c.Fodder.Id);c.Supply.TransferFromCaravan(c.Caravan.Id,c.Army.Id,c.Fodder.Id,20);Assert.That(c.Caravan.Cargo.QuantityOf(c.Fodder.Id),Is.EqualTo(before-20));Assert.That(c.Army.Supply.QuantityOf(c.Fodder.Id),Is.EqualTo(20));Assert.That(c.Caravan.Cargo.QuantityOf(c.Fodder.Id)+c.Army.Supply.QuantityOf(c.Fodder.Id),Is.EqualTo(before));}
        [Test]public void FoodFodderAndAmmo_AreExplicitRealGoodsWithDerivedShortage(){var c=Context();c.Army.AddSupplyRequirement(new SupplyRequirementState(c.Food.Id,SupplyPurpose.Food,10));c.Army.AddSupplyRequirement(new SupplyRequirementState(c.Fodder.Id,SupplyPurpose.Fodder,5));c.Army.AddSupplyRequirement(new SupplyRequirementState(c.Ammo.Id,SupplyPurpose.Ammunition,1));Assert.That(c.Army.OrderedSupplyRequirements.Select(x=>x.Purpose),Is.EqualTo(new[]{SupplyPurpose.Ammunition,SupplyPurpose.Fodder,SupplyPurpose.Food}).Or.EquivalentTo(new[]{SupplyPurpose.Food,SupplyPurpose.Fodder,SupplyPurpose.Ammunition}));Assert.That(c.Army.OrderedSupplyRequirements.Single(x=>x.Purpose==SupplyPurpose.Food).Assess(c.Army.Supply),Is.EqualTo(SupplyCondition.Exhausted));c.Supply.TransferFromCity(c.City.Id,c.Army.Id,c.Food.Id,5);Assert.That(c.Army.OrderedSupplyRequirements.Single(x=>x.Purpose==SupplyPurpose.Food).Assess(c.Army.Supply),Is.EqualTo(SupplyCondition.Insufficient));}
        [Test]public void SupplyConsumption_UsesInventoryAndReportsShortage(){var c=Context();c.Supply.TransferFromCity(c.City.Id,c.Army.Id,c.Food.Id,5);var result=c.Supply.Consume(c.Army.Id,c.Food.Id,8);Assert.That(result.Consumed,Is.EqualTo(5));Assert.That(result.Shortage,Is.EqualTo(3));Assert.That(c.Army.Supply.QuantityOf(c.Food.Id),Is.Zero);}
        [Test]public void Payroll_UsesRealMoneyPreservesArrearsAndRejectsDuplicateOrOverpayment(){var c=Context();var obligation=new PayrollObligationState(PayrollObligationId.Create("wage"),60,T(0),PayrollFundingSourceRef.CityMarket(c.City.Id));c.Army.Payroll.AddObligation(obligation);c.Payroll.Pay(c.Army.Id,obligation.Id,PayrollPaymentId.Create("pay-1"),40,T(0));Assert.That(c.Market.CashBalance.Value,Is.EqualTo(60));Assert.That(obligation.Arrears,Is.EqualTo(20));Assert.Throws<InvalidOperationException>(()=>c.Payroll.Pay(c.Army.Id,obligation.Id,PayrollPaymentId.Create("pay-1"),10,T(0)));Assert.Throws<InvalidOperationException>(()=>c.Payroll.Pay(c.Army.Id,obligation.Id,PayrollPaymentId.Create("pay-2"),21,T(0)));Assert.That(c.Market.CashBalance.Value,Is.EqualTo(60));Assert.That(obligation.Arrears,Is.EqualTo(20));}
        [Test]public void Payroll_FailsWithoutMoneyAndDoesNotSilentlyPay(){var c=Context();var obligation=new PayrollObligationState(PayrollObligationId.Create("wage"),101,T(0),PayrollFundingSourceRef.CityMarket(c.City.Id));c.Army.Payroll.AddObligation(obligation);Assert.Throws<InvalidOperationException>(()=>c.Payroll.Pay(c.Army.Id,obligation.Id,PayrollPaymentId.Create("pay"),101,T(0)));Assert.That(obligation.AmountPaid,Is.Zero);Assert.That(obligation.Arrears,Is.EqualTo(101));Assert.That(c.Market.CashBalance.Value,Is.EqualTo(100));}
        [Test]public void MoraleFatigueDisciplineSalaryAndLoyalty_RemainSeparate(){var c=Context();var loyalty=c.Commander.CurrentLoyalty.Value;c.Army.Morale.Set(MoraleAssessment.Shaken);Assert.That(c.Army.Fatigue.Assessment,Is.EqualTo(FatigueAssessment.Unassessed));Assert.That(c.Army.Discipline.Assessment,Is.EqualTo(DisciplineAssessment.Unassessed));Assert.That(c.Commander.CurrentLoyalty.Value,Is.EqualTo(loyalty));Assert.That(c.Army.Payroll.OrderedObligations,Is.Empty);}
        [Test]public void Readiness_IsProjectionAndDoesNotEraseUnderlyingTruth(){var c=Context();c.Army.Morale.Set(MoraleAssessment.Steady);c.Army.Fatigue.Set(FatigueAssessment.Fatigued);c.Army.Discipline.Set(DisciplineAssessment.Ordered);var p=new ArmyReadinessProjection(c.Army);Assert.That(p.Morale,Is.EqualTo(MoraleAssessment.Steady));Assert.That(p.Fatigue,Is.EqualTo(FatigueAssessment.Fatigued));Assert.That(p.Discipline,Is.EqualTo(DisciplineAssessment.Ordered));Assert.That(typeof(ArmyReadinessProjection).GetProperties().Any(x=>x.Name=="Score"),Is.False);}
        [Test]public void ForeignArmy_DoesNotBypassReportInformationBoundary(){var c=Context();var info=c.Runtime.Diplomacy.Information.GetRequired(FactionId.Create("observer"));Assert.That(info.OrderedAvailableReports,Is.Empty);Assert.That(c.Runtime.Military.Armies.Count,Is.EqualTo(1));Assert.Throws<System.Collections.Generic.KeyNotFoundException>(()=>info.GetRequired(ReportId.Create("army-report")));Assert.That(Enum.IsDefined(typeof(ReportSubjectKind),ReportSubjectKind.Army),Is.True);}
        [Test]public void SchemaEightRoundTrip_PreservesArmyRecruitmentSupplyPayrollAndHierarchy(){var c=Populated();var serializer=new CampaignSaveTextSerializer();var text=serializer.Serialize(CampaignSaveMapper.ToSaveData(c.Runtime));var read=serializer.Deserialize(text);Assert.That(read.Success,Is.True,read.Error);Assert.That(new CampaignSaveValidator().Validate(read.Data!).IsValid,Is.True);var restored=CampaignSaveMapper.ToRuntimeState(read.Data!);var army=restored.Military.Armies.OrderedArmies.Single();Assert.That(army.Headcount,Is.EqualTo(30));Assert.That(army.Supply.QuantityOf(c.Food.Id),Is.EqualTo(10));Assert.That(army.Payroll.OrderedObligations.Single().Arrears,Is.EqualTo(20));Assert.That(army.Command.OrderedRelationships.Count,Is.EqualTo(1));Assert.That(restored.Military.RecruitmentSources.OrderedSources.Single().AvailableHeadcount,Is.EqualTo(20));}
        [Test]public void SchemaEightSerialization_IsDeterministicAcrossInsertionOrder(){var a=Populated(false);var b=Populated(true);var serializer=new CampaignSaveTextSerializer();Assert.That(serializer.Serialize(CampaignSaveMapper.ToSaveData(a.Runtime)),Is.EqualTo(serializer.Serialize(CampaignSaveMapper.ToSaveData(b.Runtime))));}
        [Test]public void MigrationSevenToEight_PreservesPriorDomainsWithoutInventingArmy(){var c=Context();var source=CampaignSaveMapper.ToSaveData(c.Runtime);source.SaveVersion=7;var migrated=new CampaignSaveV7ToV8Migration().Apply(source);Assert.That(migrated.SaveVersion,Is.EqualTo(8));Assert.That(migrated.Characters.Count,Is.EqualTo(source.Characters.Count));Assert.That(migrated.DiplomaticActors.Count,Is.EqualTo(source.DiplomaticActors.Count));Assert.That(migrated.Armies,Is.Empty);Assert.That(migrated.RecruitmentSources,Is.Empty);}
        [Test]public void HardcodedSchemaSevenFixture_MigratesWithoutInventingMilitaryState(){const string fixture="FOC_CAMPAIGN_SAVE\nSaveVersion=7\nCampaignId=Y2FtcGFpZ24tbGVnYWN5\nGameVersion=MC4wLjc=\nContentDataVersion=ZGlwbG9tYWN5LTE=\nWorldSeed=1648\nWorldGenRevision=1\nWorldTime=9\nRngState=123\nRngDrawCount=2\nCharacterCount=0\nCharacterRelationCount=0\nSocialState=AAAAAAAAAAAAAAAA\nReligionState=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\nCityState=AAAAAA==\nEconomyState=AAAAAAAAAAAAAAAAAAAAAA==\nDiplomacyState=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=\n";var read=new CampaignSaveTextSerializer().Deserialize(fixture);Assert.That(read.Success,Is.True,read.Error);var migrated=new CampaignSaveV7ToV8Migration().Apply(read.Data!);Assert.That(migrated.SaveVersion,Is.EqualTo(8));Assert.That(migrated.Armies,Is.Empty);Assert.That(migrated.RecruitmentSources,Is.Empty);Assert.That(migrated.RecruitmentRecords,Is.Empty);}
        [Test]public void FullMigrationChain_ReachesEightWithNoFakeArmy(){var source=new CampaignSaveData{SaveVersion=1,CampaignId="legacy",GameVersion="0.1",ContentDataVersion="one",WorldSeed=1,RngState=1};var pipeline=new SaveMigrationPipeline(new ISaveMigration[]{new CampaignSaveV1ToV2Migration(),new CampaignSaveV2ToV3Migration(),new CampaignSaveV3ToV4Migration(),new CampaignSaveV4ToV5Migration(),new CampaignSaveV5ToV6Migration(),new CampaignSaveV6ToV7Migration(),new CampaignSaveV7ToV8Migration()});var result=pipeline.Migrate(source,8);Assert.That(result.Success,Is.True,result.Error);Assert.That(result.Data!.Armies,Is.Empty);Assert.That(result.Data.RecruitmentSources,Is.Empty);}
        [Test]public void SaveDataRuntimeAndBattleBoundariesRemainSeparate(){Assert.That(typeof(ArmySaveData).IsAssignableFrom(typeof(ArmyState)),Is.False);Assert.That(typeof(UnitGroupSaveData).IsAssignableFrom(typeof(UnitGroupState)),Is.False);Assert.That(typeof(ArmyState).GetProperties().Any(x=>x.Name.Contains("Battle")||x.Name.Contains("Casualt")||x.Name.Contains("Weapon")||x.Name.Contains("Armor")),Is.False);}
        [Test]public void MutationSurfaces_DoNotExposeUnfundedSupplyPayrollOrUnitInsertion(){Assert.That(typeof(ArmySupplyInventory).GetMethod("Add"),Is.Null);Assert.That(typeof(PayrollState).GetMethod("Record"),Is.Null);Assert.That(typeof(ArmyRegistry).GetMethod("AddUnit"),Is.Null);}
        [Test]public void RuntimeMilitaryInvariantValidator_AcceptsIntegratedStateAndRejectsMissingGoods(){var c=Populated();Assert.That(new MilitaryInvariantValidator().Validate(c.Runtime).IsValid,Is.True);var bad=new CampaignRuntimeState(StableId<CampaignTag>.Create("bad"),"0.7","military",1,1,new WorldClock(T(0)),new SeededRandomSource(1),c.Runtime.Characters,c.Runtime.Organizations,null,null,null,c.Runtime.Cities,new EconomyState(),c.Runtime.Diplomacy,c.Runtime.Military);Assert.That(new MilitaryInvariantValidator().Validate(bad).IsValid,Is.False);}

        private sealed class Data{public CampaignRuntimeState Runtime=null!;public ArmyCommandService Commands=null!;public ArmySupplyService Supply=null!;public ArmyPayrollService Payroll=null!;public ArmyState Army=null!;public ArmyId ArmyId;public RecruitmentSourceState Source=null!;public RecruitmentAuthorityReference Authority=null!;public CharacterState Commander=null!;public CharacterState Manager=null!;public OrganizationState Organization=null!;public AssignmentState Assignment=null!;public CityState City=null!;public CityMarketState Market=null!;public CaravanState Caravan=null!;public TradeGoodDefinition Food=null!;public TradeGoodDefinition Fodder=null!;public TradeGoodDefinition Ammo=null!;}
        private static Data Context(bool reverse=false,bool createArmy=true,bool registerSource=true)
        {var d=new Data();d.ArmyId=ArmyId.Create("army-main");var chars=new CharacterRoster();d.Commander=CharacterTestFactory.Named("commander");d.Manager=CharacterTestFactory.Named("manager");var owner=CharacterTestFactory.Named("owner");if(reverse){chars.Add(owner);chars.Add(d.Manager);chars.Add(d.Commander);}else{chars.Add(d.Commander);chars.Add(d.Manager);chars.Add(owner);}var orgs=new OrganizationRegistry();d.Organization=new OrganizationState(OrganizationId.Create("military-org"),"Military Organization");d.Assignment=new AssignmentState(AssignmentId.Create("army-command"),d.Commander.Id,OrganizationBranch.Army,"army-commander",AssignmentAuthority.FullAuthority,AssignmentTarget.Army(d.ArmyId),AssignmentPresence.PhysicalPresenceRequired,T(0));d.Organization.AddAssignment(d.Assignment);orgs.Add(d.Organization);var cities=new CityRegistry();d.City=CityTestFactory.State("city-home",reverse);d.City.GetRequiredArea(CityAreaType.Military).SetFullness(CityAreaFullness.Low);d.City.GetRequiredArea(CityAreaType.Military).ActivateBuilding(CityBuildingId.Create("barracks"));var origin=CityTestFactory.State("city-origin",!reverse);if(reverse){cities.Add(origin);cities.Add(d.City);}else{cities.Add(d.City);cities.Add(origin);}var goods=new TradeGoodRegistry();d.Food=Good("food",TradeGoodCategory.Food);d.Fodder=Good("fodder",TradeGoodCategory.RawMaterial);d.Ammo=Good("ammo",TradeGoodCategory.Military);if(reverse){goods.Add(d.Fodder);goods.Add(d.Food);goods.Add(d.Ammo);}else{goods.Add(d.Ammo);goods.Add(d.Food);goods.Add(d.Fodder);}var economy=new EconomyState(goods);var stock=new CityStockState();stock.AddInitial(new TradeGoodStock(d.Food.Id,100));stock.AddInitial(new TradeGoodStock(d.Fodder.Id,100));stock.AddInitial(new TradeGoodStock(d.Ammo.Id,100));d.Market=new CityMarketState(d.City.Id,100,stock);economy.AddMarket(d.Market);economy.AddMarket(new CityMarketState(origin.Id,100));d.Caravan=new CaravanState(CaravanId.Create("supply-caravan"),EconomicOwnerRef.Character(owner.Id),d.Manager.Id,origin.Id,d.City.Id,1000,100);d.Caravan.Cargo.Add(d.Fodder.Id,50,d.Caravan.WeightCapacity,goods);d.Caravan.MarkInTransit();d.Caravan.MarkAtDestination();economy.Caravans.Add(d.Caravan);var diplomacy=new DiplomacyState();diplomacy.Actors.Add(new DiplomaticActorState(FactionId.Create("observer"),"Observer"));diplomacy.Information.Add(new ActorInformationState(FactionId.Create("observer")));d.Runtime=new CampaignRuntimeState(StableId<CampaignTag>.Create("campaign"),"0.7","military-1",77,1,new WorldClock(T(0)),new SeededRandomSource(77),chars,orgs,null,null,null,cities,economy,diplomacy);d.Commands=new ArmyCommandService(d.Runtime);d.Supply=new ArmySupplyService(d.Runtime);d.Payroll=new ArmyPayrollService(d.Runtime);d.Authority=new RecruitmentAuthorityReference(d.Commander.Id,d.Organization.Id,d.Assignment.Id);d.Army=Army(d);if(createArmy)d.Commands.CreateArmy(d.Army);d.Source=new RecruitmentSourceState(RecruitmentSourceId.Create("garrison-source"),RecruitmentType.Garrison,50,d.Authority,d.City.Id,CityBuildingId.Create("barracks"));if(registerSource)d.Commands.RegisterRecruitmentSource(d.Source);return d;}
        private static Data Populated(bool reverse=false){var d=Context(reverse);d.Commands.Recruit(RecruitmentRecordId.Create("record"),d.Source.Id,d.Army.Id,UnitGroupId.Create("unit"),"azap",30,T(0));d.Army.Command.Add(new CommandRelationship(CommandNodeRef.Army(d.Army.Id),CommandNodeRef.Unit(UnitGroupId.Create("unit"))));d.Supply.TransferFromCity(d.City.Id,d.Army.Id,d.Food.Id,10);d.Army.AddSupplyRequirement(new SupplyRequirementState(d.Food.Id,SupplyPurpose.Food,8));var obligation=new PayrollObligationState(PayrollObligationId.Create("wage"),60,T(0),PayrollFundingSourceRef.CityMarket(d.City.Id));d.Army.Payroll.AddObligation(obligation);d.Payroll.Pay(d.Army.Id,obligation.Id,PayrollPaymentId.Create("payment"),40,T(0));d.Army.Morale.Set(MoraleAssessment.Steady);d.Army.Fatigue.Set(FatigueAssessment.Rested);d.Army.Discipline.Set(DisciplineAssessment.Ordered);return d;}
        private static ArmyState Army(Data d)=>new ArmyState(d.ArmyId,"Army",ArmyOwnerRef.Organization(d.Organization.Id),ArmyOwnerRef.Organization(d.Organization.Id),ArmyLocation.InCity(d.City.Id),new ArmyCommanderReference(d.Commander.Id,d.Organization.Id,d.Assignment.Id),ArmyLifecycle.Active);
        private static ArmyState BareArmy(string id)=>new ArmyState(ArmyId.Create(id),id,ArmyOwnerRef.MercenaryCompany("company"),ArmyOwnerRef.MercenaryCompany("company"),ArmyLocation.AtCamp(new WorldPosition(0,0)));
        private static UnitGroupState Unit(string id,ArmyId army)=>new UnitGroupState(UnitGroupId.Create(id),army,RecruitmentSourceId.Create("source"),"troop",10);
        private static RecruitmentAuthorityReference Authority()=>new RecruitmentAuthorityReference(CharacterId.Create("character"),OrganizationId.Create("org"),AssignmentId.Create("assignment"));
        private static TradeGoodDefinition Good(string id,TradeGoodCategory category)=>new TradeGoodDefinition(TradeGoodId.Create(id),id,category,1,category==TradeGoodCategory.Food,category==TradeGoodCategory.Military,category==TradeGoodCategory.Luxury);
        private static WorldTimestamp T(long value)=>new WorldTimestamp(value);
    }
}
